// th15_s7_b8 · TH15 v1.00b Extra Stage 7 BossCard4 「袋の鼠を追い詰める為の単純な弾幕」
// source: st07bs.ecl.txt:1822-1899 (BossCard4 entry)
//         BossCard4_at   1901-1922 (per-volley 20-bullet aimed stream)
//         BossCard4_at2  1924-1947 (unreachable in the 4800-frame window, see below)
//         BossCard4_at3  1949-1964 (synchronous stream driver)
// Entry state / frames: st07bs.ecl.txt:8-39 (Boss) -> (0,128), hurt 40 -> r20, hit 48 -> r24.
// HP path evidence: st07bs.ecl.txt:538 setInterrupt(0,2000,3600,...).
// Card frame 0 starts the phase; the 120-frame opening buffer is inside TIME_LIMIT.

const TIME_LIMIT: int = 4924;    // 120 opening + 4800 source window + 4 pre-timerReset
const OPENING_BUFFER: int = 120;
const PRE_RESET: int = 4;        // +2 setChapter / +2 unknown569 before timerReset (1831-1835)
const SPELL_ID: int = 112;       // 1856 spellEx(112, 4800, 500000, ...)
const TH15_OVAL: int = 672;      // 1906 etSprite(1,20,3): type20 -> OVAL, color 3
const OVAL_COLOR: int = 3;
const RAMP_FRAMES: int = 20;     // 1916 etExSet VELTIME a=20
const STREAM_BULLETS: int = 20;  // 1913 $B = 20 in BossCard4_at
const AT3_CYCLES: int = 30000;   // 1955 $C = 30000

// 1901-1922 BossCard4_at. etNew(1)/etAim(1,2)/etCount(1,1) is a single aimed
// bullet; 20 etOn calls in one frame give 20 bullets on the same aim line.
// Record 0 = type1 SPEEDUP (no main-path parameters), record 1 = VELTIME:
// a=20, r=%A (scalar target speed), s=-999999 keeps the current angle.
// s=-999999 also means the scalar ramp stays collinear with the bullet angle,
// so the 0.5 -> target scalar ramp is a plain linear speed step.
xformdef VEL_RAMP(target: fx) {
    step_speed(target, RAMP_FRAMES);
}

sub boss4_at() {
    // etAim mode2 resolves the aim from the descriptor's fire point; etDist
    // is applied per bullet afterwards, so the aim point is the boss center.
    var dir: angle = aim_player();
    var bx: fx = $self_x + 32fx * cos(dir);   // 1911 etDist(1,32)
    var by: fx = $self_y + 32fx * sin(dir);
    var target: fx = -0.8fx;                  // 1912 %A = -0.8f
    for i in 0..STREAM_BULLETS {
        // 1909 etSpeed(1,0.5,0.2): one layer, so only s0=0.5 is used.
        _ = fire(TH15_OVAL, OVAL_COLOR, bx, by, 0.5fx, dir,
                 VEL_RAMP(target), none);
        target = target + 0.5fx;              // 1917 %A += 0.5f
    }
}

async sub source_boss() {
    set_invuln(65535);   // shell invulnerability; source setInvuln paths do not drive DPS
    set_hitbox(24fx);    // Boss(): setHitbox(48,48) -> r24; body collision stays on
    set_hurtbox(20fx);   // Boss(): setHurtbox(40,40) -> r20

    // 1825-1827 ($TIMEOUT == 0 path): etCancel(640).
    clear_bullets_at($self_x, $self_y, 640fx, 0);
    // 1831-1834: setChapter(65)/unknown569(1) are chapter/stat bookkeeping and
    // are omitted; their +2/+2 = 4 frames are kept so timerReset keeps source t=4.
    wait(PRE_RESET);

    // 1835-1843 timerReset at source t=4, killAllAsync/enmKillAll: this
    // independent shell owns no inherited enemies or async tasks.
    // 1844-1854 spellEnd/funcSet(0)/laserCancel/playSound/motion reset/stats:
    // shell spell state is declared in control(); no old motion survives spawn.
    clear_bullets_at($self_x, $self_y, 640fx, 0);  // 1838-1842 second etCancel(640)
    move_vel_xy(0, 0fx, 0fx, EASE_LINEAR);         // 1848-1850 moveVel/moveVelTime/movePosTime zero

    // 1855 setInterrupt(0,0,4800,"Boss5") -> the phase timer established by
    // control(); 1856 spellEx(112,4800,500000,...) -> SPELL_ID above.
    // 1857 movePosTime(60,4,0,192).
    move_to(60, 0fx, 192fx, EASE_QUAD_OUT);
    // 1858 moveLimit(0,160,240,128) -> x in [-120,120], y in [96,224].
    // No later movement is reached before the timeout (at3 blocks), so the
    // limit never clamps an executed position.

    // 1861 +60 -> source t=64; presentation (F0/anmPlay/playSound) omitted.
    wait(60);
    // 1866 wait(60) -> source t=124. 1867-1870 set B/C and enter the outer
    // loop; 1872 B=B+1, 1873 D=3.
    wait(60);
    // 1340: wait(30) before the first @BossCard4_at3() at source t=154.
    wait(30);

    // 1949-1964 BossCard4_at3, called synchronously (no `async` in the source).
    // 1954 floatTime(0,%B,3600,0,20,10): %B = 20 - 10*t/3600 for t<3600, then 10.
    // 1959 $A=_S(%B) truncates that to the wait interval. The 30000-cycle loop
    // needs >= 300000 frames, so the outer 1000-loop, its moveRand and
    // BossCard4_at2 never run inside the 4800-frame timeout; they are therefore
    // not emitted. The spell timer is owned by control()'s enemy and is not
    // readable from this pattern-spawned boss (spell_timer() returns -1), so
    // bound the synchronous stream by the source timeout: t=0 is this task's
    // first frame, so t=4804 is the setInterrupt(...,4800) instant.
    var end_frame: int = $frame + 4804;
    var elapsed: int = 0;
    var cycles: int = AT3_CYCLES;
    while cycles > 0 && $frame < end_frame {
        boss4_at();                    // 1958 @BossCard4_at()
        var b: fx = 10fx;
        if elapsed < 3600 { b = 20fx - 10fx * (elapsed as fx) / 3600fx; }
        var dt: int = b as int;        // 1959 $A = _S(%B)
        wait(dt);                      // 1960
        elapsed = elapsed + dt;
        cycles = cycles - 1;           // 1962 if ($C--)
    }
}

async sub pattern() {
    wait(OPENING_BUFFER);
    // Boss() entry position (0,128); HP path threshold 2000.
    _ = spawn_enemy(0fx, 128fx, 2000, 0, 0, 0, source_boss);
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    spell_begin(0, SPELL_ID, pattern, TIME_LIMIT, 500000, 0, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
